/**
 * Loop protection between helpdesks.
 *
 * Outgoing system emails (ticket received, notifications, recurring tickets, ...) carry these headers so other
 * helpdesks / mail robots do not answer them or turn them into tickets (RFC 3834 + Exchange convention).
 */
export const AUTO_REPLY_HEADERS = [
  'Auto-Submitted: auto-generated',
  'X-Auto-Response-Suppress: All',
  'Precedence: auto_reply',
] as const

/** A subject that lists this many ticket numbers is a notification chain (A→B→A→…), not a real request. */
export const MAX_TICKET_NUMBERS_IN_SUBJECT = 5

/** Count `#12345`-style ticket numbers in a subject. */
export function countTicketNumbers(subject: string | null | undefined): number {
  return (String(subject ?? '').match(/#\d{4,7}\b/g) ?? []).length
}

/**
 * Was this inbound email sent by a machine (auto-reply, notification, bounce, mailing list)?
 * We never send our "ticket received" / onboarding emails back to such senders.
 */
export function isAutoGeneratedEmail(getHeader: (name: string) => string): boolean {
  const autoSubmitted = getHeader('Auto-Submitted').trim().toLowerCase()
  if (autoSubmitted && autoSubmitted !== 'no') return true
  const precedence = getHeader('Precedence').trim().toLowerCase()
  if (['bulk', 'junk', 'auto_reply', 'auto-reply'].includes(precedence)) return true
  if (getHeader('X-Auto-Response-Suppress').trim()) return true
  if (getHeader('X-Autoreply').trim() || getHeader('X-Autorespond').trim()) return true
  if (getHeader('List-Id').trim() || getHeader('List-Unsubscribe').trim()) return true
  const returnPath = getHeader('Return-Path').trim()
  if (returnPath === '<>') return true
  return false
}
